export type TokenAmounts = { token0: bigint; token1: bigint };
export type PricePoint = { token0Usd?: number; token1Usd?: number; token0Decimals: number; token1Decimals: number; blockNumber: bigint; source: string; confidence: 'verified'|'derived'|'partial'; observedAt: string };
export type LedgerEvent = { id:string; positionId:string; txHash:string; logIndex:number; kind:'mint'|'increase'|'decrease'|'collect'|'swap'|'gas'|'manual-correction'|'close'; amounts?:TokenAmounts; price?:PricePoint; gasUsd?:number; executionCostUsd?:number; reason?:string; timestamp:string };
export type CollectionAllocation = { eventId:string; principal:TokenAmounts; fees:TokenAmounts };
export type PositionLedger = { deposits:TokenAmounts; pendingPrincipal:TokenAmounts; withdrawnPrincipal:TokenAmounts; claimedFees:TokenAmounts; unclaimedFees:TokenAmounts; gasUsd:number; executionCostsUsd:number; events:LedgerEvent[]; allocations:CollectionAllocation[] };
const zero=():TokenAmounts=>({token0:0n,token1:0n});
const add=(a:TokenAmounts,b:TokenAmounts):TokenAmounts=>({token0:a.token0+b.token0,token1:a.token1+b.token1});
const take=(available:bigint, amount:bigint):[bigint,bigint]=>{const principal=available<amount?available:amount;return [principal,amount-principal];};
export class Ledger {
  private seen=new Set<string>(); private positions=new Map<string,PositionLedger>();
  state(positionId:string):PositionLedger { let p=this.positions.get(positionId); if(!p){p={deposits:zero(),pendingPrincipal:zero(),withdrawnPrincipal:zero(),claimedFees:zero(),unclaimedFees:zero(),gasUsd:0,executionCostsUsd:0,events:[],allocations:[]};this.positions.set(positionId,p);} return p; }
  ingest(e:LedgerEvent):boolean { const key=`${e.txHash}:${e.logIndex}`; if(this.seen.has(key)) return false; if(e.kind==='manual-correction'&&!e.reason) throw new Error('manual correction requires an audit reason'); this.seen.add(key); const p=this.state(e.positionId), a=e.amounts??zero(); p.events.push(e); switch(e.kind){case'mint':case'increase':p.deposits=add(p.deposits,a);break;case'decrease':p.pendingPrincipal=add(p.pendingPrincipal,a);break;case'collect':{const [p0,f0]=take(p.pendingPrincipal.token0,a.token0),[p1,f1]=take(p.pendingPrincipal.token1,a.token1);const principal={token0:p0,token1:p1},fees={token0:f0,token1:f1};p.pendingPrincipal={token0:p.pendingPrincipal.token0-p0,token1:p.pendingPrincipal.token1-p1};p.withdrawnPrincipal=add(p.withdrawnPrincipal,principal);p.claimedFees=add(p.claimedFees,fees);p.allocations.push({eventId:e.id,principal,fees});break;}case'gas':p.gasUsd+=e.gasUsd??0;break;case'swap':p.executionCostsUsd+=e.executionCostUsd??0;break;case'close':break;} return true; }
  setUnclaimedFees(positionId:string, fees:TokenAmounts):void { if(fees.token0<0n||fees.token1<0n) throw new Error('fees cannot be negative'); this.state(positionId).unclaimedFees=fees; }
}
export type Pnl = { currentLiquidityValue:number; unclaimedFeeValue:number; claimedFeeMtmValue:number; withdrawnPrincipalMtmValue:number; totalStrategyMtmValue:number; depositedValue:number; grossPnl:number; grossPnlPct:number; netPnl:number; holdValue:number; holdPnl:number; lpVsHold:number; realizedValue:number; label:'mark-to-market' };
