/** Raw token amounts are valued using the matching persisted token decimals. */
export function markToMarket(p:PositionLedger,currentLiquidity:TokenAmounts,current:PricePoint,depositValue:number,originalDeposit:TokenAmounts):Pnl { const currentLiquidityValue=value(currentLiquidity,current),unclaimedFeeValue=value(p.unclaimedFees,current),claimedFeeMtmValue=value(p.claimedFees,current),withdrawnPrincipalMtmValue=value(p.withdrawnPrincipal,current),totalStrategyMtmValue=currentLiquidityValue+unclaimedFeeValue+claimedFeeMtmValue+withdrawnPrincipalMtmValue,grossPnl=totalStrategyMtmValue-depositValue,holdValue=value(originalDeposit,current); return {currentLiquidityValue,unclaimedFeeValue,claimedFeeMtmValue,withdrawnPrincipalMtmValue,totalStrategyMtmValue,depositedValue:depositValue,grossPnl,grossPnlPct:depositValue===0?0:grossPnl/depositValue*100,netPnl:grossPnl-p.gasUsd-p.executionCostsUsd,holdValue,holdPnl:holdValue-depositValue,lpVsHold:totalStrategyMtmValue-holdValue,realizedValue:withdrawnPrincipalMtmValue,label:'mark-to-market'}; }

export type OneSidedPnlInput = { currentLiquidity:TokenAmounts; current:PricePoint; initialFunding:bigint; fundingIndex:0|1; initialFundingExecutionValue:number; realizedProceedsValue?:number; soldAssetValue?:number; targetAccumulatedRaw?:bigint; fundingRemainingRaw?:bigint; targetDecimals?:number; fundingDecimals?:number; targetPriceInFunding?:number; gasCosts?:number; executionCosts?:number };
export type OneSidedPnl = Pnl & { benchmarkAssetIndex:0|1; fundingConversionPct:number; targetAccumulatedRaw:bigint; fundingRemainingRaw:bigint; averageTargetAcquisitionPrice?:number; effectiveAcquisitionPrice?:number; breakEvenTargetPrice?:number };
/** Generic token-level one-sided accounting.  Its benchmark is explicitly the
 * original funding asset, never the old balanced HODL basket. */
export function oneSidedMarkToMarket(p:PositionLedger,input:OneSidedPnlInput):OneSidedPnl {
 const liquidity=value(input.currentLiquidity,input.current), unclaimed=value(p.unclaimedFees,input.current), claimed=value(p.claimedFees,input.current), withdrawn=value(p.withdrawnPrincipal,input.current);
 const realized=input.realizedProceedsValue??0, sold=input.soldAssetValue??0, total=liquidity+unclaimed+claimed+withdrawn+realized-sold;
 const deposited=input.initialFundingExecutionValue, gross=total-deposited;
 const fundingUsd=input.fundingIndex===0?input.current.token0Usd:input.current.token1Usd;
 const fundingDecimals=input.fundingDecimals??(input.fundingIndex===0?input.current.token0Decimals:input.current.token1Decimals);
 const holdValue=fundingUsd===undefined?NaN:Number(input.initialFunding)/10**fundingDecimals*fundingUsd;
 const fundingRemaining=input.fundingRemainingRaw??(input.fundingIndex===0?input.currentLiquidity.token0:input.currentLiquidity.token1);
 const targetAccumulated=input.targetAccumulatedRaw??(input.fundingIndex===0?input.currentLiquidity.token1:input.currentLiquidity.token0);
 const converted=input.initialFunding===0n?0:Number(input.initialFunding-fundingRemaining)/Number(input.initialFunding)*100;
 const targetDecimals=input.targetDecimals??(input.fundingIndex===0?input.current.token1Decimals:input.current.token0Decimals);
 const fundingUnits=Number(input.initialFunding)/10**fundingDecimals, targetUnits=Number(targetAccumulated)/10**targetDecimals;
 const average=targetUnits>0&&input.targetPriceInFunding!==undefined?(fundingUnits-Number(fundingRemaining)/10**fundingDecimals)/targetUnits:undefined;
 const costs=(input.gasCosts??p.gasUsd)+(input.executionCosts??p.executionCostsUsd), effective=average===undefined?undefined:average+costs/(targetUnits||1);
 const targetUsd=input.fundingIndex===0?input.current.token1Usd:input.current.token0Usd;
 const breakEven=targetUnits>0&&targetUsd!==undefined&&fundingUsd!==undefined?(deposited+costs-(total-targetUnits*targetUsd))/(targetUnits*(fundingUsd||1)):undefined;
 return {currentLiquidityValue:liquidity,unclaimedFeeValue:unclaimed,claimedFeeMtmValue:claimed,withdrawnPrincipalMtmValue:withdrawn,totalStrategyMtmValue:total,depositedValue:deposited,grossPnl:gross,grossPnlPct:deposited===0?0:gross/deposited*100,netPnl:gross-costs,holdValue,holdPnl:holdValue-deposited,lpVsHold:total-holdValue,realizedValue:withdrawn+realized, label:'mark-to-market',benchmarkAssetIndex:input.fundingIndex,fundingConversionPct:Math.max(0,Math.min(100,converted)),targetAccumulatedRaw:targetAccumulated,fundingRemainingRaw:fundingRemaining,averageTargetAcquisitionPrice:average,effectiveAcquisitionPrice:effective,breakEvenTargetPrice:breakEven};
}

