export const computeExpiresAt=(now:number,ttlMs:number)=>{if(!Number.isSafeInteger(now)||!Number.isSafeInteger(ttlMs)||ttlMs<=0)throw new Error('invalid session clock or TTL');return now+ttlMs;};
