export type DatabasePaths={dataDir:string;databasePath:string;backupDir:string};
const DIRECTORY_MODE=0o700, FILE_MODE=0o600;
function secureDirectory(path:string){mkdirSync(path,{recursive:true,mode:DIRECTORY_MODE});chmodSync(path,DIRECTORY_MODE);}
function secureFile(path:string){if(existsSync(path))chmodSync(path,FILE_MODE);}
/** Resolves production storage without relying on /tmp. Tests can supply explicit paths. */
export function productionDatabasePaths(input:{dataDir?:string;databasePath?:string}={}):DatabasePaths{
 const dataDir=resolve(input.dataDir??process.env.DATA_DIR??'./data');
 const databasePath=resolve(input.databasePath??process.env.DATABASE_PATH??join(dataDir,'robinhood-lp.sqlite'));
 return {dataDir,databasePath,backupDir:join(dataDir,'backups')};
}
function configure(db:Database.Database,busyTimeoutMs=10_000){db.pragma('foreign_keys = ON');db.pragma('journal_mode = WAL');db.pragma(`busy_timeout = ${busyTimeoutMs}`);}
/** Durable JSON boundary: exact BigInt decimal strings, including nested arrays/objects. */
export function jsonStringify(value:unknown){return JSON.stringify(value,(_,entry)=>typeof entry==='bigint'?entry.toString():entry);}
/** SQLite migration runner with an append-only schema_migrations ledger. */
export function migrateSqlite(dbPath:string,migrationsDir:string):MigrationStatus{const existed=existsSync(dbPath);secureDirectory(dirname(dbPath));const db=new Database(dbPath);try{configure(db);db.exec('CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)');const applied=new Set((db.prepare('SELECT name FROM schema_migrations').all() as {name:string}[]).map(r=>r.name));const files=readdirSync(migrationsDir).filter(x=>x.endsWith('.sql')).sort(),pendingBefore=files.filter(x=>!applied.has(x));if(existed&&pendingBefore.length){const backupDir=join(dirname(dbPath),'backups'),stamp=new Date().toISOString().replace(/[:.]/g,'-'),target=join(backupDir,`pre-migration-${pendingBefore[0]}-${stamp}.sqlite`);secureDirectory(backupDir);db.pragma('wal_checkpoint(FULL)');db.exec(`VACUUM INTO '${target.replaceAll("'","''")}'`);secureFile(target);}const insert=db.prepare('INSERT INTO schema_migrations(name,applied_at) VALUES(?,?)');for(const name of pendingBefore){const run=db.transaction(()=>{db.exec(readFileSync(join(migrationsDir,name),'utf8'));insert.run(name,new Date().toISOString());});run();applied.add(name);}secureFile(dbPath);return {applied:[...applied].sort(),pending:files.filter(x=>!applied.has(x))};}finally{db.close();}}
