/** Testable restore helper; target must not exist to avoid accidental overwrite. */
export function restoreSqliteBackup(backupPath:string,targetPath:string){if(!existsSync(backupPath))throw new Error(`backup does not exist: ${backupPath}`);if(existsSync(targetPath))throw new Error(`refusing to overwrite existing database: ${targetPath}`);secureDirectory(dirname(targetPath));copyFileSync(backupPath,targetPath);secureFile(targetPath);}
