 claimV4OperationalOpen(input:{intentId:string}){const at=new Date().toISOString(),run=this.db.transaction(()=>{const changed=this.db.prepare("UPDATE v4_live_open_intents SET state='CLAIMED',updated_at=? WHERE id=? AND state='PREVIEWED'").run(at,input.intentId).changes===1;if(changed)this.db.prepare("INSERT OR IGNORE INTO v4_live_transitions(intent_id,ordinal,state,details_json,created_at) SELECT ?,COALESCE(MAX(ordinal),-1)+1,'CLAIMED','{}',? FROM v4_live_transitions WHERE intent_id=?").run(input.intentId,at,input.intentId);return changed;});return run();}
 markV4OperationalOpenRetryable(intentId:string){const at=new Date().toISOString(),run=this.db.transaction(()=>{const changed=this.db.prepare("UPDATE v4_live_open_intents SET state='FAILED_RETRYABLE',updated_at=? WHERE id=? AND state='FAILED' AND (json_extract(payload_json,'$.lane')='operational' OR json_extract(payload_json,'$.executor')='executeV4OperationalOpen') AND erc20_approval_hash IS NULL AND permit2_approval_hash IS NULL AND mint_hash IS NULL AND NOT EXISTS(SELECT 1 FROM v4_live_gas WHERE intent_id=v4_live_open_intents.id) AND NOT EXISTS(SELECT 1 FROM v4_operational_open_receipts WHERE intent_id=v4_live_open_intents.id)").run(at,intentId).changes===1;if(changed)this.db.prepare("INSERT OR IGNORE INTO v4_live_transitions(intent_id,ordinal,state,details_json,created_at) SELECT ?,COALESCE(MAX(ordinal),-1)+1,'FAILED_RETRYABLE',?,? FROM v4_live_transitions WHERE intent_id=?").run(intentId,JSON.stringify({safeToCreateFreshIntent:true,noTransactionBroadcast:true,lane:'operational'}),at,intentId);return changed;});return run();}
 claimV4LiveClose(input:{intentId:string;tokenId:string}){const at=new Date().toISOString(),run=this.db.transaction(()=>this.db.prepare("UPDATE v4_live_canary SET state='CLOSING',close_intent_id=?,failure_reason=NULL,updated_at=? WHERE id=1 AND state='OPENED' AND token_id=?").run(input.intentId,at,input.tokenId).changes===1);return run();}
