 createV4LiveOpenIntent(input:{idempotencyKey:string;owner:string;userId?:string;chatId?:string;poolId:string;poolKey:unknown;amount:bigint;payload:unknown}){const prior=this.db.prepare('SELECT * FROM v4_live_open_intents WHERE idempotency_key=?').get(input.idempotencyKey) as Record<string,unknown>|undefined;if(prior)return prior;const id=randomUUID(),at=new Date().toISOString(),run=this.db.transaction(()=>{this.db.prepare("INSERT INTO v4_live_open_intents(id,idempotency_key,owner,telegram_user_id,telegram_chat_id,pool_id,pool_key_json,amount_raw,state,payload_json,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,? ,?,?,?)").run(id,input.idempotencyKey,input.owner,input.userId??null,input.chatId??null,input.poolId,JSON.stringify(input.poolKey),input.amount.toString(),'PREVIEWED',JSON.stringify(input.payload,(_,v)=>typeof v==='bigint'?v.toString():v),at,at);this.db.prepare("INSERT INTO v4_live_transitions(intent_id,ordinal,state,details_json,created_at) VALUES(?,0,'PREVIEWED','{}',?)").run(id,at);});run();return this.v4LiveOpenIntent(id)!;}
 v4LiveOpenIntent(id:string){return this.db.prepare('SELECT * FROM v4_live_open_intents WHERE id=?').get(id) as Record<string,unknown>|undefined;}
 transitionV4LiveOpenIntent(id:string,state:string,patch:{erc20Hash?:string;permit2Hash?:string;mintHash?:string;tokenId?:string;failureReason?:string;details?:unknown}={}){const at=new Date().toISOString(),run=this.db.transaction(()=>{this.db.prepare('UPDATE v4_live_open_intents SET state=?,erc20_approval_hash=COALESCE(?,erc20_approval_hash),permit2_approval_hash=COALESCE(?,permit2_approval_hash),mint_hash=COALESCE(?,mint_hash),token_id=COALESCE(?,token_id),failure_reason=COALESCE(?,failure_reason),updated_at=? WHERE id=?').run(state,patch.erc20Hash??null,patch.permit2Hash??null,patch.mintHash??null,patch.tokenId??null,patch.failureReason??null,at,id);this.db.prepare('INSERT OR IGNORE INTO v4_live_transitions(intent_id,ordinal,state,details_json,created_at) SELECT ?,COALESCE(MAX(ordinal),-1)+1,?,?,? FROM v4_live_transitions WHERE intent_id=?').run(id,state,JSON.stringify(patch.details??{},(_,v)=>typeof v==='bigint'?v.toString():v),at,id);});run();return this.v4LiveOpenIntent(id)!;}
 terminalizeV4OperationalNonBroadcast(input:{intentId:string;phase:string;hash:string;nonce:number;evidence:unknown}){const at=new Date().toISOString(),state=`${input.phase}_NON_BROADCAST_TERMINAL`;this.db.transaction(()=>{const row=this.v4LiveOpenIntent(input.intentId);if(!row||String(row.failure_reason)!=='V4_BROADCAST_PROVEN_ABSENT_AFTER_IDENTICAL_RESEND'||String(row.permit2_approval_hash).toLowerCase()!==input.hash.toLowerCase())throw new Error('V4_NON_BROADCAST_TERMINALIZATION_CONFLICT');this.db.prepare('UPDATE v4_live_open_intents SET state=?,failure_reason=NULL,updated_at=? WHERE id=?').run(state,at,input.intentId);this.db.prepare('INSERT OR IGNORE INTO v4_live_transitions(intent_id,ordinal,state,details_json,created_at) SELECT ?,COALESCE(MAX(ordinal),-1)+1,?,?,? FROM v4_live_transitions WHERE intent_id=?').run(input.intentId,state,JSON.stringify({phase:input.phase,exactHash:input.hash,nonce:input.nonce,classification:'PROVEN_NON_BROADCAST_SUPERSEDED_BY_SUFFICIENT_ALLOWANCE',evidence:input.evidence}),at,input.intentId);})();return this.v4LiveOpenIntent(input.intentId)!;}
 v4LiveTransitions(intentId:string){return this.db.prepare('SELECT ordinal,state,details_json,created_at FROM v4_live_transitions WHERE intent_id=? ORDER BY ordinal').all(intentId) as Record<string,unknown>[];}
 addV4LiveGasEstimate(input:{txHash:string;intentId:string;phase:string;gas:bigint;eth:bigint;usd:number}){this.db.prepare('INSERT OR IGNORE INTO v4_live_gas(tx_hash,intent_id,phase,estimated_gas,estimated_eth_raw,estimated_usd,created_at) VALUES(?,?,?,?,?,?,?)').run(input.txHash,input.intentId,input.phase,input.gas.toString(),input.eth.toString(),input.usd,new Date().toISOString());}
 confirmV4LiveGas(input:{txHash:string;gas:bigint;eth:bigint;usd:number}){const at=new Date().toISOString(),run=this.db.transaction(()=>{const changed=this.db.prepare('UPDATE v4_live_gas SET actual_gas=?,actual_eth_raw=?,actual_usd=?,confirmed_at=? WHERE tx_hash=? AND actual_gas IS NULL').run(input.gas.toString(),input.eth.toString(),input.usd,at,input.txHash).changes;if(changed)this.db.prepare('UPDATE v4_live_canary SET gas_spent_eth_raw=CAST(CAST(gas_spent_eth_raw AS INTEGER)+? AS TEXT),gas_spent_usd=gas_spent_usd+?,updated_at=? WHERE id=1').run(input.eth.toString(),input.usd,at);return changed;});return run();}
 confirmV4OperationalGas(input:{txHash:string;gas:bigint;eth:bigint;usd:number}){const at=new Date().toISOString();return this.db.prepare('UPDATE v4_live_gas SET actual_gas=?,actual_eth_raw=?,actual_usd=?,confirmed_at=? WHERE tx_hash=? AND actual_gas IS NULL').run(input.gas.toString(),input.eth.toString(),input.usd,at,input.txHash).changes>0;}
