 supersedeV4PoolSelections(userId:string,chatId:string,sessionId:string){return this.db.prepare('UPDATE v4_pool_selections SET superseded=1 WHERE user_id=? AND chat_id=? AND session_id=? AND superseded=0').run(userId,chatId,sessionId).changes;}
